/**
 * PM workbench panel body.
 *
 * The panel is a host, not a view: the workbench itself is a static page served
 * by this plugin's node half, so the browser half only embeds it and bridges
 * the interactions the page cannot perform for itself — opening a Session and,
 * for Phase 2, enqueueing the summary prompt into that Session so the
 * conversation summarizes itself. Navigation reuses the shared Host probe and
 * fallbacks; a refused prompt is reported rather than silently ignored.
 */

import { useEffect, useRef, useState, type CSSProperties } from 'react'

/** Injected share of the panel: Session navigation for one bridge request. */
export interface PmPanelInjected {
  /**
   * Open the Session one workbench card names.
   * @param sessionId - Session id from the workbench.
   * @param instance - work-memory instance that recorded the card.
   * @returns a notice to show, or null when navigation succeeded.
   */
  readonly openSession: (sessionId: string, instance: string) => Promise<string | null>
  /**
   * Send the summary prompt into the Session itself (Phase 2: the conversation
   * writes its own one-line summary).
   * @param sessionId - Session id from the workbench.
   * @param prompt - prompt text to enqueue.
   * @returns a notice to show, or null when the prompt was accepted.
   */
  readonly runPrompt: (sessionId: string, prompt: string, open?: boolean) => Promise<string | null>
}

/** One accepted `pm-open-session` bridge request. */
export interface PmBridgeRequest {
  /** Session the workbench asked to open. */
  readonly sessionId: string
  /** work-memory instance that recorded the card. */
  readonly instance: string
}

/** One accepted `pm-run-prompt` bridge request. */
export interface PmPromptRequest {
  /** Session the workbench asked to summarize. */
  readonly sessionId: string
  /** Prompt text the Session should receive. */
  readonly prompt: string
  /** Whether the host should bring the Session to the main column; batch sends keep it false. */
  readonly open: boolean
}

/** Message type the workbench posts to its host. */
const OPEN_SESSION = 'pm-open-session'

/** Message type that enqueues a prompt into the named Session. */
const RUN_PROMPT = 'pm-run-prompt'

/** Message type the host answers a prompt request with. */
const PROMPT_RESULT = 'pm-run-prompt-result'

/** Instance label used when the workbench omits the field. */
const UNKNOWN_INSTANCE = 'unknown'

/**
 * Read one prompt bridge message.
 * @param data - the message payload as received.
 * @returns the request, or null when the message is not one this panel serves.
 */
export function promptRequest(data: unknown): PmPromptRequest | null {
  if (typeof data !== 'object' || data === null) return null
  const message = data as { readonly type?: unknown; readonly sessionId?: unknown; readonly prompt?: unknown }
  if (message.type !== RUN_PROMPT) return null
  if (typeof message.sessionId !== 'string' || message.sessionId === '') return null
  if (typeof message.prompt !== 'string' || message.prompt.trim() === '') return null
  const messageOpen = (data as { readonly open?: unknown }).open
  return { sessionId: message.sessionId, prompt: message.prompt, open: messageOpen !== false }
}

/**
 * Read one workbench bridge message.
 * @param data - the message payload as received.
 * @returns the request, or null when the message is not one this panel serves.
 */
export function bridgeRequest(data: unknown): PmBridgeRequest | null {
  if (typeof data !== 'object' || data === null) return null
  const message = data as { readonly type?: unknown; readonly sessionId?: unknown; readonly instance?: unknown }
  if (message.type !== OPEN_SESSION) return null
  if (typeof message.sessionId !== 'string' || message.sessionId === '') return null
  return {
    sessionId: message.sessionId,
    instance: typeof message.instance === 'string' && message.instance !== '' ? message.instance : UNKNOWN_INSTANCE,
  }
}

/** Base used when there is no document to resolve against (server render, tests). */
const NO_DOCUMENT_BASE = 'http://localhost/'

/**
 * Document-relative URL of the hosted workbench.
 * @param base - document base URI to resolve against.
 * @param sessionId - foreground Session, passed through so the page can filter
 *   the AI-handoff session list by the Session project.
 * @returns the workbench URL, so a mounted base path keeps working.
 */
export function workbenchUrl(base?: string, sessionId?: string): string {
  const resolved = base ?? (typeof document === 'undefined' ? NO_DOCUMENT_BASE : document.baseURI)
  const url = new URL('ui-pm/app/', resolved)
  if (sessionId !== undefined && sessionId !== '') url.searchParams.set('sessionId', sessionId)
  return url.href
}

/** Panel shell: the workbench fills it, with a floor so the frame cannot collapse. */
const shell: CSSProperties = {
  display: 'flex', flexDirection: 'column', gap: '8px',
  height: '100%', minHeight: '560px', padding: '8px',
}
const noticeStyle: CSSProperties = { fontSize: '12px', color: '#d9c48b', margin: 0 }
const frameStyle: CSSProperties = {
  flex: '1 1 auto', width: '100%', minHeight: '520px',
  border: '0', borderRadius: '8px', background: 'transparent',
}

/**
 * Render the embedded PM workbench and bridge its Session requests.
 * @param props.openSession - injected Session navigation.
 * @param props.runPrompt - injected prompt enqueue for "let the conversation summarize itself".
 * @param props.sessionId - foreground Session when hosted in the right Sidebar.
 * @returns the panel body.
 */
export function PmPanel({ openSession, runPrompt, sessionId }: PmPanelInjected & { readonly sessionId?: string }) {
  const frame = useRef<HTMLIFrameElement | null>(null)
  const [notice, setNotice] = useState<string | null>(null)
  const [busy, setBusy] = useState(false)

  useEffect(() => {
    const listener = (event: MessageEvent): void => {
      // Only the frame this panel mounted may steer the panel.
      if (event.source !== frame.current?.contentWindow) return
      const prompt = promptRequest(event.data)
      if (prompt !== null) {
        setBusy(true)
        setNotice(null)
        void runPrompt(prompt.sessionId, prompt.prompt, prompt.open)
          .then((outcome) => {
            setNotice(outcome)
            // The workbench shows its own status; a failed enqueue must not look sent.
            frame.current?.contentWindow?.postMessage(
              { type: PROMPT_RESULT, sessionId: prompt.sessionId, error: outcome }, '*')
          })
          .finally(() => { setBusy(false) })
        return
      }
      const request = bridgeRequest(event.data)
      if (request === null) return
      setBusy(true)
      setNotice(null)
      void openSession(request.sessionId, request.instance)
        .then((outcome) => { setNotice(outcome) })
        .finally(() => { setBusy(false) })
    }
    window.addEventListener('message', listener)
    return () => { window.removeEventListener('message', listener) }
  }, [openSession])

  return (
    <div style={shell} data-pm-panel="" data-pm-view="workbench">
      {(notice !== null || busy) && (
        <p style={noticeStyle} role="status" data-pm-notice="">
          {busy ? 'Opening the Session…' : notice}
        </p>
      )}
      <iframe
        ref={frame}
        data-pm-frame=""
        title="PM workbench"
        src={workbenchUrl(undefined, sessionId)}
        sandbox="allow-scripts allow-same-origin allow-forms allow-modals"
        style={frameStyle}
      />
    </div>
  )
}
